function CreateKeyDialog({
  open,
  onOpenChange,
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
}) {
  const { user } = Route.useRouteContext()
  const { error, setError, pending, run } = useAction()
  const [key, setKey] = useState('')

  async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const name = String(new FormData(event.currentTarget).get('name'))
    await run(async () => setKey(await createApiKey({ data: { name } })))
  }

  const origin = typeof window === 'undefined' ? '' : window.location.origin
  const settings = [
    ['Username', user.username],
    ['Password', key],
    ['KOReader sync server', `${origin}/kosync`],
    ['OPDS catalog', `${origin}/opds`],
  ]

  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        if (next) return
        setError('')
        setKey('')
        onOpenChange(false)
      }}
    >
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>{key ? 'Key created' : 'Create key'}</DialogTitle>
        </DialogHeader>
        {key ? (
          <>
            <dl className="grid gap-3 text-sm">
              {settings.map(([label, value]) => (
                <div key={label} className="grid gap-1">
                  <dt className="text-muted-foreground">{label}</dt>
                  <dd className="font-mono break-all select-all">{value}</dd>
                </div>
              ))}
            </dl>
            <DialogFooter>
              <Button
                onClick={() => {
                  setKey('')
                  onOpenChange(false)
                }}
              >
                Done
              </Button>
            </DialogFooter>
          </>
        ) : (
          <form onSubmit={onSubmit} className="grid gap-4">
            <div className="grid gap-2">
              <Label htmlFor="key-name">Device</Label>
              <Input
                id="key-name"
                name="name"
                placeholder="Kobo Libra"
                autoComplete="off"
                maxLength={50}
                required
              />
            </div>
            {error && <p className="text-sm text-destructive">{error}</p>}
            <DialogFooter>
              <Button type="submit" disabled={pending}>
                Create key
              </Button>
            </DialogFooter>
          </form>
        )}
      </DialogContent>
    </Dialog>
  )
}

function DeleteKeyDialog({
  apiKey,
  onClose,
}: {
  apiKey: ApiKey | null
  onClose: () => void
}) {
  const { error, setError, pending, run } = useAction()

  async function onConfirm(event: React.MouseEvent) {
    // Keep the dialog open until the request finishes so errors show inline.
    event.preventDefault()
    if (!apiKey) return
    const ok = await run(() => deleteApiKey({ data: { id: apiKey.id } }))
    if (ok) onClose()
  }

  return (
    <AlertDialog
      open={apiKey !== null}
      onOpenChange={(open) => {
        if (open) return
        setError('')
        onClose()
      }}
    >
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>Delete {apiKey?.name}?</AlertDialogTitle>
        </AlertDialogHeader>
        {error && <p className="text-sm text-destructive">{error}</p>}
        <AlertDialogFooter>
          <AlertDialogCancel>Cancel</AlertDialogCancel>
          <AlertDialogAction
            variant="destructive"
            disabled={pending}
            onClick={onConfirm}
          >
            Delete
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
